const rawInput = $input.first().json;
const payload = rawInput.body || rawInput;
const isEmptyPayload = !payload || Object.keys(payload).length === 0;

let rawKeywords = [];
if (Array.isArray(payload.keywords)) {
  rawKeywords = payload.keywords;
} else if (typeof payload.csvText === 'string') {
  rawKeywords = payload.csvText.split(/\r?\n/).map(line => line.split(',')[0]).filter(Boolean);
} else if (isEmptyPayload) {
  // Manual test run - a small bundled sample spanning a few topics
  rawKeywords = [
    'email marketing software', 'best email marketing software', 'email marketing software for small business',
    'free email marketing tools', 'email marketing automation', 'email marketing templates',
    'how to write a marketing email', 'email subject line ideas', 'email marketing metrics to track',
    'project management software', 'best project management software', 'free project management tools',
    'project management software for small teams', 'agile project management tools', 'gantt chart software',
    'kanban board software', 'how to run a sprint retrospective', 'project management certification',
    'crm software', 'best crm for small business', 'free crm software', 'crm vs erp',
    'sales pipeline management', 'customer relationship management examples'
  ];
}

const maxKeywords = Number(payload.maxKeywords) || 10000;

const seen = new Set();
const normalizedKeywords = [];
for (const entry of rawKeywords) {
  const kw = typeof entry === 'string' ? entry : (entry && entry.keyword);
  if (!kw) continue;
  const trimmed = String(kw).trim();
  const key = trimmed.toLowerCase();
  if (!trimmed || seen.has(key)) continue;
  seen.add(key);
  normalizedKeywords.push({
    keyword: trimmed,
    searchVolume: (entry && Number(entry.searchVolume)) || null,
    cpc: (entry && Number(entry.cpc)) || null
  });
  if (normalizedKeywords.length >= maxKeywords) break;
}

return [{
  json: {
    normalizedKeywords,
    totalKeywordsIngested: normalizedKeywords.length
  }
}];

const state = $input.first().json;

const STOP_AND_MODIFIER_WORDS = new Set([
  'a', 'an', 'the', 'and', 'or', 'for', 'to', 'of', 'in', 'on', 'with', 'vs', 'versus', 'is', 'are',
  'how', 'what', 'why', 'when', 'where', 'best', 'top', 'cheap', 'free', 'affordable', 'review',
  'reviews', 'guide', 'near', 'me', '2024', '2025', '2026', '2027'
]);

function tokenize(keyword) {
  return keyword.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
}
function coreTokens(tokens) {
  return tokens.filter(t => !STOP_AND_MODIFIER_WORDS.has(t) && !/^\d+$/.test(t));
}

const clusterMap = {};
for (const item of state.normalizedKeywords) {
  const tokens = tokenize(item.keyword);
  const core = coreTokens(tokens).sort();
  const signature = core.join('-') || tokens.sort().join('-') || item.keyword.toLowerCase();
  if (!clusterMap[signature]) {
    clusterMap[signature] = { signature, coreTokens: core, keywords: [] };
  }
  clusterMap[signature].keywords.push(item);
}

const rawClusters = Object.values(clusterMap);

return [{
  json: {
    ...state,
    rawClusters,
    rawClusterCount: rawClusters.length
  }
}];

const state = $input.first().json;

function scoreForPrimary(k) {
  // Prefer higher search volume when known; otherwise prefer shorter, more generic phrasing
  return (k.searchVolume || 0) * 1000000 - k.keyword.length;
}

const clusters = state.rawClusters.map(cluster => {
  const sorted = [...cluster.keywords].sort((a, b) => scoreForPrimary(b) - scoreForPrimary(a));
  const primaryKeyword = sorted[0];
  const supportingKeywords = sorted.slice(1);
  return {
    signature: cluster.signature,
    coreTokens: cluster.coreTokens,
    keywordCount: cluster.keywords.length,
    primaryKeyword: primaryKeyword.keyword,
    supportingKeywords: supportingKeywords.map(k => k.keyword),
    sampleKeywordsForPrompt: [primaryKeyword, ...supportingKeywords].slice(0, state.maxSampleKeywordsPerClusterForPrompt).map(k => k.keyword)
  };
});

return [{
  json: {
    ...state,
    clusters
  }
}];

const state = $input.first().json;
const batchSize = state.batchSize || 50;
const clusters = state.clusters || [];

const clusterBatchQueue = [];
for (let i = 0; i < clusters.length; i += batchSize) {
  clusterBatchQueue.push(clusters.slice(i, i + batchSize));
}

return [{
  json: {
    ...state,
    clusterBatchQueue,
    labeledClusters: []
  }
}];

const item = $input.first().json;
const clusterBatchQueue = [...(item.clusterBatchQueue || [])];
const nextBatch = clusterBatchQueue.shift();

return [{
  json: {
    ...item,
    clusterBatchQueue,
    currentBatch: nextBatch || [],
    hasNextBatch: !!nextBatch
  }
}];

const aiResponse = $input.first().json;
const state = $('Code 5 - Get Next Cluster Batch From Queue').first().json;

let parsed;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { clusters: [] };
}

const labelBySignature = {};
for (const c of (parsed.clusters || [])) {
  labelBySignature[c.signature] = { clusterTopic: c.clusterTopic, suggestedPillar: c.suggestedPillar };
}

const newlyLabeled = (state.currentBatch || []).map(cluster => {
  const label = labelBySignature[cluster.signature] || { clusterTopic: cluster.primaryKeyword, suggestedPillar: 'Uncategorized' };
  return {
    ...cluster,
    clusterTopic: label.clusterTopic,
    suggestedPillar: label.suggestedPillar
  };
});

return [{
  json: {
    ...state,
    labeledClusters: [...(state.labeledClusters || []), ...newlyLabeled]
  }
}];

const state = $('IF - Cluster Batch Queue Empty').first().json;
const labeledClusters = state.labeledClusters || [];

const pillarCounts = {};
for (const c of labeledClusters) {
  const key = (c.suggestedPillar || 'Uncategorized').trim();
  if (!pillarCounts[key]) pillarCounts[key] = { rawLabel: key, clusterCount: 0, sampleClusterTopics: [] };
  pillarCounts[key].clusterCount += 1;
  if (pillarCounts[key].sampleClusterTopics.length < 5) pillarCounts[key].sampleClusterTopics.push(c.clusterTopic);
}

const distinctPillars = Object.values(pillarCounts).sort((a, b) => b.clusterCount - a.clusterCount);

return [{
  json: {
    ...state,
    distinctPillars,
    distinctPillarCount: distinctPillars.length
  }
}];

const aiResponse = $input.first().json;
const state = $('Code 7 - Aggregate Distinct Suggested Pillars').first().json;

let parsed;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { canonicalPillars: [] };
}

const pillarMapping = {};
for (const p of (parsed.canonicalPillars || [])) {
  for (const rawLabel of (p.mergedFromLabels || [])) {
    pillarMapping[rawLabel.trim().toLowerCase()] = p.pillarName;
  }
}

// Safety net: any raw label the AI didn't place becomes its own pillar
for (const p of state.distinctPillars) {
  const key = p.rawLabel.trim().toLowerCase();
  if (!pillarMapping[key]) pillarMapping[key] = p.rawLabel;
}

return [{
  json: {
    ...state,
    pillarMapping
  }
}];

const state = $input.first().json;

function slugify(text) {
  return String(text).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

const pillarsMap = {};
for (const cluster of (state.labeledClusters || [])) {
  const rawKey = (cluster.suggestedPillar || 'Uncategorized').trim().toLowerCase();
  const pillarName = state.pillarMapping[rawKey] || cluster.suggestedPillar || 'Uncategorized';
  if (!pillarsMap[pillarName]) {
    pillarsMap[pillarName] = { pillarName, pillarSlug: slugify(pillarName), clusters: [] };
  }
  pillarsMap[pillarName].clusters.push({
    clusterTopic: cluster.clusterTopic,
    clusterSlug: slugify(cluster.clusterTopic),
    hubPageKeyword: cluster.primaryKeyword,
    supportingPages: cluster.supportingKeywords.map(kw => ({ keyword: kw, slug: slugify(kw) })),
    supportingPageCount: cluster.supportingKeywords.length,
    totalKeywordsInCluster: cluster.keywordCount
  });
}

const pillars = Object.values(pillarsMap).map(p => ({
  ...p,
  clusterCount: p.clusters.length,
  totalKeywords: p.clusters.reduce((s, c) => s + c.totalKeywordsInCluster, 0)
})).sort((a, b) => b.totalKeywords - a.totalKeywords);

const totalClusters = pillars.reduce((s, p) => s + p.clusterCount, 0);
const totalSupportingPages = pillars.reduce((s, p) => s + p.clusters.reduce((s2, c) => s2 + c.supportingPageCount, 0), 0);

return [{
  json: {
    ...state,
    pillars,
    architectureSummary: {
      totalKeywordsIngested: state.totalKeywordsIngested,
      totalPillars: pillars.length,
      totalClusters,
      totalSupportingPages
    }
  }
}];

const aiResponse = $input.first().json;
const state = $('Code 9 - Assemble Final Site Architecture').first().json;

let review;
try {
  const raw = aiResponse.content?.[0]?.text || '{}';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  review = JSON.parse(cleaned);
} catch (e) {
  review = { architectureAssessment: 'Unable to parse AI response', thinPillars: [], broadPillars: [], internalLinkingRecommendation: '', suggestedPillarPriority: [] };
}

const finalReport = {
  summary: state.architectureSummary,
  pillars: state.pillars,
  architectureReview: review,
  generatedAt: new Date().toISOString()
};

return [{
  json: {
    ...state,
    finalReport
  }
}];
